create table public.user_gold (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  balance integer not null default 0 check (balance >= 0),
  total_earned integer not null default 0 check (total_earned >= 0),
  total_spent integer not null default 0 check (total_spent >= 0),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.gold_transactions (
  id bigint generated by default as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade,
  amount integer not null, transaction_type text not null check (transaction_type in ('EARN','SPEND')),
  reason text not null, description text, balance_after integer not null check (balance_after >= 0), created_at timestamptz not null default now()
);
alter table public.user_gold enable row level security; alter table public.gold_transactions enable row level security;
create policy "gold: user or manager reads" on public.user_gold for select to authenticated using ((select auth.uid())=user_id or (select private.is_manager()));
create policy "gold transactions: user or manager reads" on public.gold_transactions for select to authenticated using ((select auth.uid())=user_id or (select private.is_manager()));
grant select on public.user_gold,public.gold_transactions to authenticated; grant all on public.user_gold,public.gold_transactions to service_role;
insert into public.user_gold(user_id) select id from public.profiles on conflict do nothing;
create or replace function private.initialize_gold_data() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.user_gold(user_id) values(new.id) on conflict do nothing; return new; end; $$;
create trigger profiles_initialize_gold_data after insert on public.profiles for each row execute procedure private.initialize_gold_data();
create or replace function public.exchange_points_to_gold(p_points_amount integer) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_user uuid:=auth.uid(); v_gold integer; v_points integer; v_gold_balance integer;
begin
 if v_user is null then raise exception 'Authentication is required' using errcode='28000'; end if;
 if p_points_amount is null or p_points_amount<1000 or p_points_amount%1000<>0 then raise exception 'Points must be exchanged in 1,000-point units' using errcode='22023'; end if;
 v_gold:=p_points_amount/1000;
 select balance into v_points from public.user_points where user_id=v_user for update;
 if coalesce(v_points,0)<p_points_amount then raise exception 'Insufficient points' using errcode='P0001'; end if;
 update public.user_points set balance=balance-p_points_amount,total_spent=total_spent+p_points_amount,updated_at=now() where user_id=v_user;
 insert into public.point_transactions(user_id,amount,transaction_type,reason,description,balance_after) values(v_user,-p_points_amount,'SPEND','GOLD_EXCHANGE',v_gold||' gold exchange',v_points-p_points_amount);
 insert into public.user_gold(user_id,balance,total_earned) values(v_user,v_gold,v_gold) on conflict(user_id) do update set balance=public.user_gold.balance+excluded.balance,total_earned=public.user_gold.total_earned+excluded.total_earned,updated_at=now() returning balance into v_gold_balance;
 insert into public.gold_transactions(user_id,amount,transaction_type,reason,description,balance_after) values(v_user,v_gold,'EARN','POINTS_EXCHANGE',p_points_amount||' points exchange',v_gold_balance);
 return jsonb_build_object('pointsSpent',p_points_amount,'goldEarned',v_gold,'exchangeRate',1000,'goldBalance',v_gold_balance,'pointsBalance',v_points-p_points_amount);
end; $$;
revoke all on function public.exchange_points_to_gold(integer) from public,anon; grant execute on function public.exchange_points_to_gold(integer) to authenticated;
